aryWeaponTexture}/{n.SecondaryWeaponTexture} | Light {n.Light} | Spawn filter {n.SpawnConditionValueFilter} time {n.SpawnMinTime}..{n.SpawnMaxTime} expansions {n.SpawnMinExpansion}..{n.SpawnMaxExpansion} flags +[{n.SpawnContentFlags}] -[{n.SpawnContentFlagsDisabled}]",WaypointEntityData w=>$"Waypoint grid {w.GridId} #{w.Number} | pause {w.Pause}s center {w.CenterPoint} | wander {w.WanderType} pause type {w.PauseType}",GroundSpawnEntityData g=>$"Ground spawn item {g.ItemId} max {g.MaxAllowed} | bounds X {g.MinX:0.00}..{g.MaxX:0.00} Y {g.MinY:0.00}..{g.MaxY:0.00} Z {g.MaxZ:0.00} | respawn {g.RespawnTimer}s fixZ {g.FixZ} | v{g.Version} expansions {g.MinExpansion}..{g.MaxExpansion} | flags +[{g.ContentFlags}] -[{g.ContentFlagsDisabled}] | {g.Comment}",ObjectEntityData o=>$"DB object v{o.Version} | Item {o.ItemId} charges {o.Charges} | Type {o.Type} icon {o.Icon} | size% {o.SizePercentage:0.00} native {o.NativeSize:0.00} | unknown {o.Unknown24}/{o.Unknown60}/{o.Unknown64}/{o.Unknown68}/{o.Unknown72}/{o.Unknown76}/{o.Unknown84} | solid {o.SolidType} incline {o.Incline} tilt {o.TiltX:0.00}/{o.TiltY:0.00} | expansions {o.MinExpansion}..{o.MaxExpansion} | flags +[{o.ContentFlags}] -[{o.ContentFlagsDisabled}] | display {o.DisplayName} | contents {o.Contents?.Count??0}"+((o.Contents?.Count??0)>0?$" [{string.Join("; ",o.Contents!.Take(8).Select(x=>$"bag{x.BagIndex}:item{x.ItemId}x{x.Charges}"))}]":""),EqgLightEffectEntityData e=>$"Sage V4 LightFX | alt {e.AltName} unknown {e.Unknown}/{e.Unknown1:0.###} | rotation {e.RotateX:0.###},{e.RotateY:0.###},{e.RotateZ:0.###} | scale {e.ScaleX:0.###},{e.ScaleY:0.###},{e.ScaleZ:0.###} | source parser preserves this record; pinned Sage exporter does not consume it",EcoLayerEntityData e=>$"ECO {e.LayerKind} {e.EcoName}/{e.LayerName} | native {e.NativeReference} texture layer {e.TextureLayer} | density {e.Density:0.###} iterations {e.Iterations} | scale {e.MinScale:0.###}..{e.MaxScale:0.###} alpha {e.MinAlpha:0.###} | height {e.MinHeight:0.###}..{e.MaxHeight:0.###} tol {e.HeightTolerance:0.###} | slope {e.MinSlope:0.###}..{e.MaxSlope:0.###} tol {e.SlopeTolerance:0.###}",ActorEntityData a=>$"Actor radius {a.BoundingRadius:0.00}"+(string.IsNullOrWhiteSpace(a.SoundName)?"":$" | Sound {a.SoundName}")+(a.VertexColorReference is int vc?$" | Vertex color ref {vc}":"")+(string.IsNullOrWhiteSpace(a.UserData)?"":$" | User data {a.UserData}"),DoorEntityData d=>$"Door ID {d.DoorId} | Open type {d.OpenType} | Version {d.Version} | Lockpick {d.Lockpick} | Key {d.KeyItem} | Trigger {d.TriggerDoor}/{d.TriggerType} | Open {d.DoorIsOpen} | Dest {d.DestZone}#{d.DestInstance} {d.DestX:0.00},{d.DestY:0.00},{d.DestZ:0.00} h {d.DestHeading:0.00} | Invert {d.InvertState} | Incline {d.Incline}",LightEntityData l=>$"Light radius {l.Radius:0.00} | Frames {l.Frames.Count} | Current {l.CurrentFrame} | Sleep {l.Sleep}"+(l.GlobalAmbient?" | Global ambient":""),RegionEntityData r=>$"Region {string.Join(", ",r.Semantics)}"+(r.ZoneLineReference is int rr?$" | zoneline ref {rr}":r.TargetZoneIndex is int zi?$" | zone {zi} target {r.TargetX},{r.TargetY},{r.TargetZ} rot {r.TargetRotation}":"")+(r.ExtentX!=0||r.ExtentY!=0||r.ExtentZ!=0?$" | extents {r.ExtentX:0.00},{r.ExtentY:0.00},{r.ExtentZ:0.00} flags {r.SourceFlag1}/{r.SourceFlag2} source {r.SourceName}":""),ZonePointEntityData p=>$"Zone point {p.Number} v{p.Version} -> zone {p.TargetZoneId} instance {p.TargetInstance} | target {p.TargetX:0.00}, {p.TargetY:0.00}, {p.TargetZ:0.00} h {p.TargetHeading:0.00} | zoneinst {p.ZoneInstance} | buffer {p.Buffer:0.00} | client mask 0x{p.ClientVersionMask:X8} | expansions {p.MinExpansion}..{p.MaxExpansion} | virtual {p.IsVirtual} {p.Width}x{p.Height} | flags +[{p.ContentFlags}] -[{p.ContentFlagsDisabled}]",_=>null};if(detail is not null)InspectorPanel.Children.Add(new System.Windows.Controls.TextBlock{Text=detail,TextWrapping=TextWrapping.Wrap});StatusText.Text=$"Selected {entity.Name}";_ = RenderModelViewerAsync(entity);}
 void PopulateAssetViewers(CompleteZone zone){ObjectList.Items.Clear();foreach(var e in zone.Entities.Where(x=>x.Kind is ZoneEntityKind.StaticObject or ZoneEntityKind.AnimatedObject).OrderBy(x=>x.Name))ObjectList.Items.Add(new System.Windows.Controls.ListBoxItem{Content=e.Name,Tag=e.Id});TextureList.Items.Clear();if(_client is not null)foreach(var t in _client.TextureFiles.Keys.OrderBy(x=>x))TextureList.Items.Add(t);MaterialList.Items.Clear();if(_client is not null)foreach(var m in _client.RenderMeshes.Values.SelectMany(x=>x.Primitives).Select(x=>x.Material?.Name).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x=>x))MaterialList.Items.Add(m);PopulateActiveZoneAssetTree(zone);}
 void PopulateActiveZoneAssetTree(CompleteZone zone){AssetTree.Items.Clear();AssetTreeScrollBar.Value=0;var filter=AssetSearchBox.Text?.Trim()??"";var root=new System.Windows.Controls.TreeViewItem{Header=zone.ShortName,IsExpanded=true};foreach(var group in new[]{(ZoneEntityKind.WorldGeometry,"World Geometry"),(ZoneEntityKind.StaticObject,"Objects"),(ZoneEntityKind.AnimatedObject,"Animated Objects"),(ZoneEntityKind.Light,"Lights"),(ZoneEntityKind.Region,"Regions"),(ZoneEntityKind.Door,"Doors"),(ZoneEntityKind.Npc,"NPCs"),(ZoneEntityKind.Spawn,"Spawns"),(ZoneEntityKind.GroundSpawn,"Ground Spawns"),(ZoneEntityKind.ZonePoint,"Zone Points")}){var all=zone.Entities.Where(x=>x.Kind==group.Item1).ToArray();var shown=string.IsNullOrWhiteSpace(filter)?all:all.Where(x=>x.Name.Contains(filter,StringComparison.OrdinalIgnoreCase)||group.Item2.Contains(filter,StringComparison.OrdinalIgnoreCase)).ToArray();if(shown.Length==0&&!string.IsNullOrWhiteSpace(filter))continue;var branch=new System.Windows.Controls.TreeViewItem{Header=$"{group.Item2} ({all.Length})",IsExpanded=!string.IsNullOrWhiteSpace(filter)};foreach(var e in shown.OrderBy(x=>x.Name)){var item=new System.Windows.Controls.TreeViewItem{Header=e.Name,Tag=e.Id};item.Selected+=(_,args)=>{if(_session?.ActiveZone is not{} active||!active.Contains(e.Id))return;_selectedId=e.Id;ShowInspector(active.Get(e.Id));_ = ScriptAsync($"window.ddvwf?.selectId?.('{e.Id}')");args.Handled=true;};branch.Items.Add(item);}root.Items.Add(branch);}AssetTree.Items.Add(root);}
 void AssetTree_PreviewMouseWheel(object sender,System.Windows.Input.MouseWheelEventArgs e){var viewer=FindVisualChild<System.Windows.Controls.ScrollViewer>(AssetTree);if(viewer is null)return;viewer.ScrollToVerticalOffset(viewer.VerticalOffset-e.Delta/3.0);SyncAssetTreeScrollBar(viewer);e.Handled=true;}
 void AssetTreeScrollBar_ValueChanged(object sender,RoutedPropertyChangedEventArgs<double> e){var viewer=FindVisualChild<System.Windows.Controls.ScrollViewer>(AssetTree);if(viewer is not null&&Math.Abs(viewer.VerticalOffset-e.NewValue)>.1)viewer.ScrollToVerticalOffset(e.NewValue);}
 void SyncAssetTreeScrollBar(System.Windows.Controls.ScrollViewer viewer){AssetTreeScrollBar.Minimum=0;AssetTreeScrollBar.Maximum=Math.Max(0,viewer.ScrollableHeight);AssetTreeScrollBar.ViewportSize=Math.Max(0,viewer.ViewportHeight);AssetTreeScrollBar.SmallChange=1;AssetTreeScrollBar.LargeChange=Math.Max(1,viewer.ViewportHeight*.9);AssetTreeScrollBar.Value=Math.Min(AssetTreeScrollBar.Maximum,viewer.VerticalOffset);}
 static T? FindVisualChild<T>(System.Windows.DependencyObject root) where T:System.Windows.DependencyObject{for(var i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++){var child=System.Windows.Media.VisualTreeHelper.GetChild(root,i);if(child is T match)return match;var nested=FindVisualChild<T>(child);if(nested is not null)return nested;}return null;}
